import type { PluginManifest, PluginModule, PluginState } from "./types";

export class Plugin {
	private state: PluginState = "disabled";

	/** 同清单id */
	id: string;
	manifest: PluginManifest;

	module: PluginModule;

	constructor(dir: string, manifest: PluginManifest, module: PluginModule) {
		this.manifest = manifest;
		this.id = manifest.id;
		
		this.module = module;
	}

	async init() {

		await this.module.init();
	}

}

import fs from "fs/promises";
import path from "path";
import type { PluginManifest } from "./types";
import { Plugin } from "./plugin";
import { PLuginLoader } from "./loader";

export class PluginManager {
	loader = new PLuginLoader();
	plugins = new Map<string, Plugin>()
	/**
	 * 加载插件清单
	 * @param dir 插件目录, 是包含插件清单的目录
	 */
	async load(dir: string) {
		// 枯燥的读文件解析json并验证关键字段
		const file = await fs.readFile(path.resolve(dir, "manifest.json"), "utf8");
		const manifest = JSON.parse(file) as PluginManifest;
		if (!manifest.id) throw new Error(`插件缺少 id 声明, 文件"${dir}/manifest.json"`);
		if (!manifest.version) throw new Error(`插件 ${manifest.id} 缺少 version 声明`);

		manifest.path = path.resolve(dir);

		console.log(`加载清单: ${manifest.id} - ${manifest.version}`);

		const module = (await this.loader.load(path.resolve(dir, manifest.main))).default
		let plugin = new Plugin(dir, manifest, module);

		plugin.init()
	}

	/**
	 * 扫描插件, 从左往右加载, 后扫描会覆盖先扫描
	 * @param args 插件目录
	 */
	async scan(...args: string[]) {
		for (let dir of args) {			
			const pdirs = await fs.readdir(dir);
			for (let pdir of pdirs) {				
				this.load(path.resolve(dir, pdir));
			}
		}
	}
}

import esbuild from "esbuild";

export class PLuginLoader {
	/**
	 * 构建插件代码并导出插件模块
	 * @param filename 
	 */
	async load(filename: string) {
		const option: esbuild.BuildOptions = {
			bundle: true,
			write: false,
			entryPoints: [filename],
			format: "iife",
			platform: "node",
			globalName: "module"
		}

		const output = await esbuild.build(option);

		const code = output.outputFiles?.[0]?.text;
		if (!code) throw new Error(`构建产物为空`)
		return new Function(`${code};return module;`)();

	}

	/**
	 * 检查是否为合法导入
	 * @param url 模块绝对路径
	 */
	private _availableImport(url: string): boolean {
		return false;
	}
}

export type PluginState = "enabled" | "disabled" | "pendeding";

export type PluginDependencies = Record<string, string>;

export type PluginManifest = {
	id: string;
	version: string;
	author?: string;
	name?: string;
	description?: string;


	path: string;

	main: string;

	dependencies?: PluginDependencies[];
}

export type PluginModule = {
	init(): void | Promise<void>;

	unload(): void | Promise<void>;
}

export default {
	init(ctx) {
		console.log("ping plugin loaded");
	}
}

